return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10 >= 2 && n%10<=4 &&(n%100<10||n%100 >= 20)? 1 : 2);','language'=>'ru_RU','project-id-version'=>'#1 RW Wordpress Addon','pot-creation-date'=>'2026-09-17T10:36:17+00:00','po-revision-date'=>'2025-11-16 15:36+0000','x-generator'=>'Loco https://localise.biz/','messages'=>['# WP Excellence Addon'=>'# WP Excellence Addon','Transforms your standard WordPress installation into an excellent, optimized website with comprehensive performance, security, and usability enhancements.'=>'Превращает вашу стандартную установку WordPress в превосходный оптимизированный веб-сайт с комплексными улучшениями производительности, безопасности и удобства использования.','Aleksey Tikhomirov'=>'Aleksey Tikhomirov','https://rwsite.ru'=>'https://rwsite.ru','Additional shortcodes <b>email:</b>'=>'Дополнительные шорткоды <b>email:</b>','Specify date and time in format: 00.00.0000 00:00 or use the calendar'=>'Укажите дату и время в формате: 00.00.0000 00:00 или воспользуйтесь календарем','Cookie consent'=>'До контента','Plugin list of '=>'Список плагинов','Users role info'=>'Информация о ролях','Server info'=>'ИНФОРМАЦИЯ О СЕРВЕРЕ','Off'=>'Выкл','On'=>'Вкл','Welcome to '=>'Добро пожаловать в','Maintenance Mode'=>'Режим тех. работ','Maintenance message'=>'Сообщение на странице техработ','Sorry, the site is temporarily unavailable due to maintenance. Please try again later.'=>'Извините, сайт временно недоступен из-за технических работ. Пожалуйста, попробуйте зайти позже.','Custom text shown on the maintenance page. Leave empty to use the default message.'=>'Пользовательский текст на странице техработ. Оставьте пустым, чтобы использовать сообщение по умолчанию.','Maintenance IP whitelist'=>'Белый список IP для режима техработ','One IP address per line. Whitelisted IPs can browse the site while maintenance mode is active.'=>'Один IP-адрес на строку. Адреса из белого списка могут просматривать сайт во время техработ.','Maintenance role whitelist'=>'Белый список ролей для режима техработ','Selected roles can browse the site while maintenance mode is active. Administrators always have access.'=>'Выбранные роли могут просматривать сайт во время техработ. Администраторы всегда имеют доступ.','Maintenance'=>'Технические работы','Access denied.'=>'Доступ запрещен.','No files to delete.'=>'Нет файлов для удаления.','Total size: %s MB'=>'Общий размер: %s МБ','Files to delete:'=>'Файлы для удаления:','Deleted %d files.'=>'Удалено %d файлов.',' Errors: %d.'=>'Ошибки: %d.','Ads manager'=>'Менеджер рекламы','Enable this extension?'=>'Включить это расширение?','Change to On for enable this.'=>'Измените значение на «Вкл.», чтобы включить это.','Ads in content'=>'Реклама в контенте','Displays HTML content in the selected location of the post'=>'Отображает HTML-контент в выбранном месте поста.','Before content'=>'До контента','ADs Mode'=>'Режим рекламы','Off to run html mode'=>'Выключите, чтобы запустить режим HTML','Link'=>'Связь','Banner html code'=>'HTML-код баннера','Select post type'=>'Выбор post type','In content'=>'В содержании','After content'=>'После контента','Enable jQuery ADs mode'=>'Включить режим jQuery AD','Advanced Advertising mode. For developers.'=>'Режим расширенной рекламы. Для разработчиков.','Displays HTML content in the selected jQuery selector, anywhere on the site.'=>'Отображает HTML-контент в выбранном селекторе jQuery в любом месте сайта.','Add Banner Image'=>'Добавить изображение баннера','Remove Image'=>'Удалить изображение','jQuery selector'=>'селектор jQuery','Example: #div'=>'Пример: #div','Banner code'=>'Код баннера','Guid repair'=>'Ремонт Guid','View all GUID'=>'Просмотреть все GUID','Update all GUID'=>'Обновить все идентификаторы GUID','All revision'=>'Все ревизии','Remove all revision'=>'Удалить все ревизии','FAQ'=>'Часто задаваемые вопросы','Elements'=>'Элементы','Question'=>'Вопрос','Question for answer'=>'Вопрос для ответа','Any widgets'=>'Любые виджеты','Widget Name'=>'Имя виджета','Paste Original Widget Class Name. See: https://codex.wordpress.org/Template_Tags/the_widget'=>'Вставьте исходное имя класса виджета. См.: https://codex.wordpress.org/Template_Tags/the_widget.','Instance'=>'Пример','Instance Params'=>'Параметры экземпляра','Args'=>'Аргументы','Enter description.'=>'Введите описание.','Widget not found!'=>'Виджет не найден!','Custom Default Avatar'=>'Аватар по умолчанию','User avatar'=>'Аватар пользователя','Additional sidebar 1'=>'Дополнительная боковая панель 1','Additional sidebar 2'=>'Дополнительная боковая панель 2','Additional sidebar 3'=>'Дополнительная боковая панель 3','Clone'=>'клонировать','Clone this Widget'=>'Клонирование виджетов','VK'=>'ВК','OK'=>'OK','Failed to delete files license.txt and readme.html from folder %s. Please delete them manually!'=>'Не удалось удалить файлы license.txt и readme.html из папки %s. Пожалуйста, удалите их вручную!','Files license.txt and readme.html have been deleted from folder %s.'=>'Файлы license.txt и readme.html были удалены из папки %s.','filter...'=>'фильтр...','Read more ...'=>'Подробнее...','Error:'=>'Ошибки: %d.','Banner position'=>'Код баннера','Banner text'=>'Код баннера','Shows an "Under maintenance" page to all visitors except administrators. Useful when updating the theme, plugins, or migrating content.'=>'Показывает страницу «Технические работы» всем посетителям, кромеадминистраторов. Удобно при обновлении темы, плагинов или переносе контента.','Show custom fields for categories and posts'=>'Показать custom fields для категорий и сообщений','Restores the standard Custom Fields meta box on post edit screens. Needed when you work with meta fields without a separate plugin.'=>'Возвращает стандартный блок «Произвольные поля» на экранах редактированиязаписей. Нужен, если вы работаете с meta-полями без отдельного плагина.','⚠️ Disable all updates.'=>'Отключить все обновления','Fully disables automatic and background updates for core, plugins, and themes. Use only on staging or when you control updates manually. When enabled, it also covers Tweaks "Block WordPress.org update HTTP requests" and "Disable aggressive update".'=>'Полностью отключает автоматические и фоновые обновления ядра, плагинов итем. Используйте только на staging или при ручном контроле обновлений. Привключении также перекрывает твики «Block WordPress.org update HTTP requests»и «Disable aggressive update».','Posts and Page Settings'=>'Настройки постов и страниц','Show posts IDs'=>'Показывать ID','Adds an ID column to post, page, and media lists. Handy for shortcodes, SQL queries, and debugging.'=>'Добавляет колонку ID в списки записей, страниц и медиафайлов. Удобно дляшорткодов, SQL-запросов и отладки.','Show posts thumbnails'=>'Показывать миниатюры записей','Shows the post thumbnail in the Posts admin table. Helps you quickly find posts with a featured image.'=>'Показывает миниатюру записи в таблице «Записи» в админке. Помогает быстронаходить материалы с обложкой.','Enable duplicate post and page'=>'Включить дублирование поста и страницы','Adds a Duplicate action for posts and pages. Creates a draft copy with the same content.'=>'Добавляет действие «Дублировать» для записей и страниц. Создаёт черновик-копию с тем же содержимым.','Removes /category/ from category URLs. After enabling or disabling, flush permalinks in WordPress.'=>'Убирает /category/ из URL рубрик. После включения или отключения нужносбросить постоянные ссылки в WordPress.','Enables pretty URLs for nested tags such as /tag/git/submodules/. The rewrite rule maps to the final tag slug, not the full path.'=>'Включает красивые URL для вложенных тегов вида /tag/git/submodules/. Правиловедёт на конечный slug тега, а не на весь путь.','Change length post excerpt? To maximum 200 symbols.'=>'Изменить длину отрывка из поста? Максимум до 200 символов.','Trims manual or automatic excerpts to about 180 characters with an ellipsis. Useful for post cards and SEO snippets.'=>'Обрезает ручную или автоматическую выдержку до ~180 символов с многоточием.Полезно для карточек записей и SEO-сниппетов.','⚠️ Don`t allow to show specific categories in frontend.'=>'Запретить отображение определенных категорий во внешнем интерфейсе.','Hides selected categories on the frontend: posts are excluded from archives and feeds, and a direct visit to a category archive redirects to the home page.'=>'Скрывает выбранные рубрики на сайте: записи не попадут в архивы и ленты, апрямой заход на архив рубрики перенаправит на главную.','Exclude specific categories of posts. Enter categories ID, separated by commas. Before ID you need a minus sign.'=>'Исключить определённые категории публикаций. Введите идентификатор категории через запятую. Перед идентификатором необходимо поставить знак минус.','Enter category IDs separated by commas. A leading minus is optional — the plugin normalizes IDs automatically. Example: 6137, 24990.'=>'Укажите ID рубрик через запятую. Минус перед числом необязателен — плагинсам приведёт ID к нужному формату. Пример: 6137, 24990.','Comment form'=>'Форма комментариев','Disable comments'=>'Отключить все комментарии','Disables comments on the site. If no post types are selected below, comments are disabled everywhere. If you select post types, comments stay enabled only where you need them.'=>'Отключает комментарии на сайте. Если ниже не выбраны типы записей —отключение будет для всех типов. Если выбрать типы — комментарии останутсятолько там, где они нужны.','Post types without comments'=>'Типы записей без комментариев','Select post types where comments should be disabled. If nothing is selected, comments are disabled everywhere.'=>'Выберите типы записей, где комментарии нужно отключить. Если ничего невыбрано — комментарии отключаются везде.','Posts'=>'Записи','Pages'=>'Страницы','Media'=>'Медиафайлы','Disable link Nofollow in comment'=>'Отключить ссылку Nofollow в комментарии','Removes rel="nofollow" from comment author links. Enable only if you intentionally pass link equity from comments.'=>'Убирает rel="nofollow" у ссылок авторов комментариев. Включайте только если осознанно передаёте ссылочный вес из комментариев.','Remove site field in comment'=>'Удалить поле сайта в комментарии','Hides the Website field in the comment form. Reduces spam and avoids asking readers for extra data.'=>'Скрывает поле «Сайт» в форме комментария. Снижает спам и не просит лишнихданных у читателей.','TinyMCE Settings'=>'Настройки TinyMCE','⚠️ Disable guttenber?'=>'Отключить Гуттенберг','Restores the classic TinyMCE editor instead of the block editor for all post types. On newer WordPress versions it may conflict with plugins built for blocks. For the widget screen only, use Shortcodes and Widgets → Disable Gutenberg for widgets.'=>'Возвращает классический редактор TinyMCE вместо блокового Gutenberg для всехтипов записей. На новых версиях WordPress может конфликтовать с плагинами,рассчитанными на блоки. Для экрана виджетов используйте Shortcodes andWidgets → Disable Gutenberg for widgets.','Add a pack color to tinyMCE'=>'Добавьте пак цветов в tinyMCE','Adds an extended text and background color palette in the visual editor.'=>'Добавляет расширенную палитру цветов текста и фона в визуальном редакторе.','Enable "Open Sans" google font for tinyMCE.'=>'Включить шрифт Google "Open Sans" для TinyMCE.','Loads the Open Sans font in the editor preview. Works independently of TinyMCE Advanced.'=>'Подключает шрифт Open Sans в предпросмотр редактора. Работает независимо отрасширенной панели TinyMCE Advanced.','Add TinyMCE Advanced functions'=>'Добавить расширенные функции TinyMCE','Adds a second toolbar: fonts, sizes, tables, subscript/superscript, and extra formatting buttons.'=>'Добавляет вторую панель инструментов: шрифты, размеры, таблицы,подстрочные/надстрочные символы и дополнительные кнопки форматирования.','Enable CSS framework in editor'=>'Подключить CSS-фреймворк в редакторе','Loads a CSS framework into the TinyMCE preview and adds a button to insert framework markup. Needed when content uses grid and component classes.'=>'Подключает CSS-фреймворк в предпросмотр TinyMCE и кнопку вставки разметки.Нужен, если в контенте используются классы сетки и компонентов.','CSS framework for TinyMCE preview'=>'CSS-фреймворк для предпросмотра TinyMCE','Bootstrap 3 is the main option for the current theme and shortcodes. Bootstrap 5 and Tailwind are additional preview options. For Tailwind, you can add assets/css/tailwind-editor.css to the theme.'=>'Bootstrap 3 — основной сценарий для текущей темы и шорткодов. Bootstrap 5 иTailwind — дополнительные варианты для предпросмотра. Для Tailwind можноположить assets/css/tailwind-editor.css в тему.','Bootstrap 3'=>'Bootstrap 3','Bootstrap 5'=>'Bootstrap 5','Tailwind CSS'=>'Tailwind CSS','Add table plugin'=>'Добавить плагин таблиц','Enables creating and editing tables in TinyMCE with ready-made Bootstrap CSS classes.'=>'Включает создание и редактирование таблиц прямо в TinyMCE, с готовыми CSS-классами Bootstrap.','SEO Settings'=>'Настройки SEO','Set Alt in updload from Title media'=>'Установите Alt при обновлении загрузки с заголовка медиа-файла','If an uploaded image has an empty alt attribute, uses the media library title. Helps with accessibility and SEO.'=>'Если у загруженного изображения пустой alt, подставляет заголовок файла измедиабиблиотеки. Помогает не забывать про доступность и SEO.','Enable transliteration?'=>'Включить транслитерацию?','Transliterates Cyrillic to Latin for post, category, and filename slugs. Handy for Russian sites with Latin URLs.'=>'Переводит кириллицу в латиницу для slug записей, рубрик и имён файлов.Удобно для русскоязычных сайтов с латинскими URL.','⚠️ Disable site indexing.'=>'Отключить индексацию сайта.','Adds meta robots noindex on every page of the site. Use on test or staging hosts so search engines do not index a draft site. Different from Tweaks "Noindex for search, attachment and date archives", which only targets low-value archive pages.'=>'Добавляет meta robots noindex на все страницы сайта. Используйте на тестовомили staging-хосте, чтобы поисковики не индексировали черновой сайт.Отличается от твика «Noindex for search, attachment and date archives»,который закрывает только архивы.','Data Base Optimization'=>'Оптимизая БД','Write right link to guid for New posts.'=>'Напишите правильную ссылку на guid for New posts.','When saving a new post, writes its permalink into guid instead of a temporary ?p=ID URL. Useful for RSS and some integrations.'=>'При сохранении новой записи записывает в поле guid её постоянную ссылкувместо временного ?p=ID. Полезно для RSS и некоторых интеграций.','⚠️ This option enable interface for replace wp guide to right GUID.'=>'Эта опция включает интерфейс для замены wp guide на правильный GUID.','Opens an admin tool for bulk viewing and replacing GUID values. Change GUIDs deliberately — RSS subscribers may receive duplicate items.'=>'Открывает в админке инструмент массового просмотра и замены GUID. МеняйтеGUID только осознанно: подписчики RSS могут получить дубликаты материалов.','Admin dashboard widgets'=>'Виджеты панели администратора','Add all types at a glance widget'=>'Добавить все типы в виджет "glance"','Expands the At a Glance widget on the admin dashboard: shows all public post types, taxonomies, and the user count.'=>'Расширяет виджет «Прямо сейчас» на главной админки: показывает все публичныетипы записей, таксономии и число пользователей.','Plugins list'=>'Список плагинов сайта','Adds a list of installed plugins with versions to the dashboard. Visible to administrators only.'=>'Добавляет на рабочий стол список установленных плагинов с версиями. Видентолько администраторам.','Shows server, domain, and WP_DEBUG information. Useful for diagnostics, but avoid enabling on shared hosting unless needed.'=>'Показывает техническую информацию о сервере, домене и режиме WP_DEBUG.Полезно для диагностики, но не включайте на shared-хостинге безнеобходимости.','Adds a WordPress roles list widget to the dashboard. Helps you recall role slugs when configuring permissions.'=>'Добавляет виджет со списком ролей WordPress на рабочем столе. Помогаетбыстро вспомнить slug роли при настройке прав.','Contact Form 7 settings'=>'CF7 настройки','Show additional shortcode?'=>'Показать дополнительный шорткод?','Shows a hint with extra CF7 shortcodes: date, time, URL, IP, and user agent. Handy when collecting technical data from a form.'=>'Показывает подсказку с дополнительными шорткодами CF7: дата, время, URL, IPи user agent. Удобно при сборе технических данных из формы.','Polylang settings'=>'Настройки Polylang','Hide languages in wp Front. Enter lang slug, separated: ", ".'=>'Скрыть языки в WP Front. Введите название языка, разделённое: ", ".','List of Polylang language slugs to hide in the frontend switcher. Example: en, de. Spaces after commas are allowed.'=>'Список slug языков Polylang, которые нужно скрыть в переключателе на фронте.Пример: en, de. Пробелы после запятой допустимы.','Remove WP-Version in Header'=>'Удалить WP-версию в шапке','Removes the WordPress version number from page HTML and RSS. A small security measure: attackers have a harder time targeting a specific WP version.'=>'Убирает номер версии WordPress из HTML-кода страницы и RSS. Это небольшаямера безопасности: злоумышленнику сложнее подобрать эксплойт под конкретнуюверсию WP.','WP-Emojis deacivation'=>'Деактивация WP-Emojis','Disables WordPress emoji scripts and styles. Pages load faster, especially if you do not use emoji in content.'=>'Отключает смайлики WordPress и лишние скрипты/стили для них. Страницыгрузятся быстрее, особенно если вы не используете emoji в контенте.','Remove Windows Live Writer'=>'Удалить Windows Live Writer','Removes the wlwmanifest link from the head. It was only needed for the old Windows Live Writer app and is not required on modern sites.'=>'Удаляет служебную ссылку wlwmanifest из <head>. Она нужна только старойпрограмме Windows Live Writer и современным сайтам не требуется.','Remove RSD-Link'=>'Удалить RSD-ссылку','Removes the RSD link for external editors. It is an extra technical tag in the head that is usually unused.'=>'Убирает RSD-ссылку для внешних редакторов. Это лишний технический тег в<head>, который обычно не используется.','⚠️ Remove RSS links'=>'Удалить RSS ссылки','Removes RSS feed links from the head. Enable only if you are sure RSS is not needed. For a blog it is usually better to leave this off so readers and aggregators can find your feed.'=>'Убирает ссылки на RSS-ленту из <head>. Включайте только если RSS вам точноне нужен. Для блога обычно лучше оставить выключенным — так читатели иагрегаторы найдут вашу ленту.','Remove shortlink in the header'=>'Удалить короткую ссылку в шапке','Removes the shortlink — a short service URL for the page. It is not needed for SEO or visitors.'=>'Удаляет shortlink — короткую служебную ссылку на страницу. Для SEO ипользователей она не нужна.','Remove adjacent links to posts in the header'=>'Удалите смежные ссылки на посты в заголовке','Removes link rel="prev/next" from the head. If the theme already outputs previous/next post navigation, this tag is redundant.'=>'Убирает link rel="prev/next" из <head>. Если тема сама выводит навигацию «предыдущая/следующая запись», этот тег избыточен.','Set limit post revisions to 5'=>'Установить ограничение на ревизий постов в 5','Limits the number of saved post revisions to 5. This reduces database size without hurting day-to-day editing.'=>'Ограничивает число автосохранённых ревизий записи до 5. Это уменьшает размербазы данных без потери рабочего комфорта.','Blocks background requests to api.wordpress.org and downloads.wordpress.org. Useful on closed servers, but WordPress will stop checking core, plugin, and theme updates. Skipped automatically when General Settings → Disable all updates is enabled.'=>'Блокирует фоновые запросы к api.wordpress.org и downloads.wordpress.org.Полезно на закрытых серверах, но WordPress перестанет сам проверятьобновления. Автоматически не применяется, если в General Settings включено«Disable all updates».','Disables Heartbeat on the public site and slows it down in the admin. This reduces extra AJAX requests. Post autosave remains, but runs less often.'=>'Отключает Heartbeat на публичной части сайта и замедляет его в админке. Этоснижает лишние AJAX-запросы. В редакторе постов автосохранение остаётся, нореже.','⚠️ Remove jQuery Migrate'=>'Удалить jQuery Migrate','Removes jquery-migrate on the frontend. It may speed up the site but can break older themes and plugins. Enable only after checking forms, sliders, and menus.'=>'Убирает jquery-migrate на фронте. Может ускорить сайт, но иногда ломаетстарые темы и плагины. Включайте только после проверки форм, слайдеров именю.','Disable new themes on major WP updates'=>'Отключайте новые темы в основных обновлениях WP','Prevents WordPress from installing a new default theme during a major core update. Convenient if you use only your own theme.'=>'Не устанавливать новую стандартную тему WordPress при крупном обновленииядра. Удобно, если вы используете только свою тему.','Disable XML-RPC'=>'Отключить XML-RPC','Disables XML-RPC — an old interface for remote publishing and some attacks. If you do not publish via external XML-RPC apps, it is safer to keep this enabled.'=>'Отключает XML-RPC — старый интерфейс для удалённой публикации и некоторыхатак. Если вы не публикуете посты через внешние приложения по XML-RPC, лучшедержать включённым.','Remove post by email function'=>'Функция удаления сообщения по электронной почте','Disables publishing posts by email. Almost nobody needs this feature, and it is better to close an unused entry point.'=>'Отключает публикацию записей по e-mail. Эта функция почти никому не нужна, алишний вход в систему лучше закрыть.','⚠️ Disable agressive update'=>'Отключить агрессивное обновление','Disables automatic update checks on every admin visit. Reduces load, but even administrators will not see update notices until they open Updates manually. Skipped automatically when General Settings → Disable all updates is enabled.'=>'Отключает автоматическую проверку обновлений при каждом заходе в админку.Снижает нагрузку, но даже администратор не увидит напоминания обобновлениях, пока не зайдёт в «Обновления» вручную. Автоматически неприменяется, если в General Settings включено «Disable all updates».','Disable URL auto-linking in comments'=>'Отключить автоматическую привязку URL-адресов в комментариях','Stops URLs in comments from being turned into clickable links automatically. Useful against spam and unwanted outbound links in comments. Different from General Settings → Disable link Nofollow in comment, which only removes rel="nofollow".'=>'Не превращает URL в комментариях автоматически в кликабельные ссылки. Полезно против спама и лишних исходящих ссылок. Отличается от General Settings → Disable link Nofollow in comment, который только убирает rel="nofollow".','Remove login-shake on errors'=>'Удалить логин-уведомления при ошибках','Removes the login form shake on wrong username or password. It does not affect site behavior — only the login page animation.'=>'Убирает «тряску» формы входа при ошибке логина/пароля. На работу сайта невлияет, просто делает страницу входа спокойнее.','Empty WP-Trash every 14 days'=>'Очищать WP-корзину каждые 14 дней','Automatically empties the WordPress trash after 14 days. Helps keep deleted posts and comments from bloating the database.'=>'Автоматически очищает корзину WordPress через 14 дней. Помогает не раздуватьбазу удалёнными записями и комментариями.','⚠️ Allow download types file: SVG, DOC, djv ..'=>'Разрешить загрузку типов файлов: SVG, DOC, djv..','Allows uploading additional file types: SVG, DOC, WebP, and others. SVG is handy for icons but may contain malicious code — upload only trusted files. Also adds WebP and SVG MIME types; use settings 34 and 35 below for media library preview support.'=>'Разрешает загрузку дополнительных типов файлов: SVG, DOC, WebP и др. SVGудобны для иконок, но могут содержать вредоносный код — загружайте толькопроверенные файлы. Также добавляет MIME-типы WebP и SVG; для предпросмотра вмедиабиблиотеке используйте настройки 34 и 35 ниже.','Disable pingback from this site to this site'=>'Отключить pingbackи сайта','Prevents the site from sending pingbacks to itself. This is useless load and sometimes a source of spam.'=>'Запрещает сайту отправлять pingback самому себе. Это бесполезная нагрузка ииногда источник спама.','Hide adminbar in frontend for contributors, authors and subscribers'=>'Скрыть панель администратора в интерфейсе для участников, авторов и подписчиков','Hides the admin bar on the frontend for authors, contributors, and subscribers. Editors and administrators still see it.'=>'Скрывает чёрную админ-панель на сайте для авторов, участников и подписчиков.Редакторы и администраторы по-прежнему её видят.','Add VK and OK to user profile'=>'Добавить ВК и ОК в профиль пользователя','Adds VK and Odnoklassniki fields to the user profile and removes outdated AIM/Jabber/Yahoo IM fields.'=>'Добавляет поля VK и Odnoklassniki в профиль пользователя и убираетустаревшие AIM/Jabber/Yahoo IM.','Showing usages memory and time generate site page'=>'Отображение использования памяти и времени создания страницы сайта','Shows page generation time and memory usage in an HTML comment at the bottom of the page. Visible only to administrators. Better to leave off on production.'=>'Показывает в HTML-комментарии внизу страницы время генерации и расходпамяти. Видно только администратору. Для продакшена лучше выключить.','⚠️ Remove Standard WP widget'=>'Удалить стандартный виджет WP','Removes all default WordPress widgets from the available list. Dangerous on unfamiliar sites: you can lose already configured sidebar blocks.'=>'Удаляет все стандартные виджеты WordPress из списка доступных. Опасновключать на чужом сайте: можно потерять уже настроенные блоки в сайдбарах.','AutoRemove readme.html and license.txt files'=>'Автоудаление readme.html and license.txt файлов','Deletes readme.html and license.txt from the site root when an administrator opens the admin. These files can reveal the WordPress version to outsiders.'=>'Удаляет readme.html и license.txt из корня сайта при заходе администратора вадминку. Эти файлы могут подсказать версию WordPress посторонним.','Adds a search field above category and tag lists in the post editor. Very helpful when you have many terms.'=>'Добавляет поле поиска над списком рубрик и меток при редактировании записи.Очень удобно, если категорий и тегов много.','Does not move selected categories and tags to the top of the list. Makes long category trees easier to scan.'=>'Не поднимает выбранные рубрики и метки наверх списка. Так прощеориентироваться в длинном дереве категорий.','If posts have status "pending" show numbers it in menu'=>'Если сообщения имеют статус «ожидание», показывать их номера в меню.','Shows a Pending count next to the Posts menu item in the admin.'=>'Показывает счётчик записей «На модерации» рядом с пунктом «Записи» в админ-меню.','Showing message "Update wordpress" only admin'=>'Отображение сообщения "Обновить wordpress" только для администратора','Hides WordPress update notices from editors, authors, and other users without administrator rights.'=>'Скрывает уведомления об обновлении WordPress от редакторов, авторов и другихпользователей без прав администратора.','Repalse [...] to "Read more ..." for posts'=>'Заменить [...] на «Читать далее...» для сообщений','Replaces the default [...] excerpt marker with a Read more... link.'=>'Заменяет стандартное [...] в анонсе записи на ссылку «Читать далее...».','Allow shortcode in "Text" widget'=>'Разрешить шорткод в виджете «Текст»','Allows shortcodes to run in text and block widgets. Needed if you insert [shortcode] directly into a widget.'=>'Разрешает выполнение шорткодов в текстовых и блочных виджетах. Нужно, есливы вставляете [shortcode] прямо в виджет.','⚠️ Get jquery from google cloud'=>'Получить jquery из Google Cloud','Loads jQuery from Google CDN instead of the WordPress bundled version. It may speed up loading but often breaks theme and plugin compatibility. Better to leave off by default.'=>'Подключает jQuery с CDN Google вместо версии WordPress. Может ускоритьзагрузку, но часто ломает совместимость с темой и плагинами. По умолчаниюлучше не включать.','Disables automatic <p> wrapping around shortcodes. Needed only if layout around shortcodes breaks. Not required on most sites.'=>'Отключает автоматическую расстановку <p> вокруг шорткодов. Нужно только есливерстка вокруг шорткодов «ломается». На большинстве сайтов не требуется.','Allow WEBP support for media'=>'Разрешить поддержку WEBP для мультимедиа','Allows uploading and previewing WebP images in the media library. WebP is also allowed by setting 19 above; this option adds preview support in the library.'=>'Разрешает загрузку и просмотр изображений WebP в медиабиблиотеке. WebP такжеразрешает настройка 19 выше; эта опция добавляет поддержку предпросмотра.','Allow SVG support for media'=>'Разрешить поддержку SVG для мультимедиа','Helps SVG files display correctly in the media library. Works together with setting 19 above, which allows SVG uploads.'=>'Помогает корректно показывать SVG-файлы в медиабиблиотеке. Работает вместе снастройкой 19 выше, которая разрешает загрузку SVG.','Disable browser checking in dashboard'=>'Отключить проверку браузера в панели управления','Disables outdated browser checks in the WordPress dashboard. Removes an extra request to WordPress.org and annoying warnings.'=>'Отключает проверку устаревшего браузера в консоли WordPress. Убирает лишнийзапрос к WordPress.org и назойливые предупреждения.','Shows a generic Incorrect username or password message instead of hints like that user does not exist. This improves login page security.'=>'Показывает общее сообщение «Неверный логин или пароль» вместо подсказоквроде «такого пользователя не существует». Это повышает безопасностьстраницы входа.','Extends the login cookie to 1 year when Remember Me is checked. Without the checkbox the default session length stays unchanged. Do not enable on shared computers.'=>'Продлевает cookie-сессию до 1 года, если при входе отмечено «Запомнитьменя». Без галочки срок остаётся стандартным. Не включайте на общихкомпьютерах.','Disables the wp-embed.js script WordPress loads for post embeds. On a regular site it is rarely needed and saves a few kilobytes.'=>'Отключает скрипт wp-embed.js, который WordPress подключает для встраиваниязаписей. На обычном сайте он почти не нужен и экономит несколько килобайт.','Does not load dashicons CSS for logged-out visitors. Saves about 30 KB if the frontend has no admin UI elements.'=>'Не загружает CSS-иконки dashicons для неавторизованных посетителей. Экономит~30 KB, если на фронте нет элементов админки.','Closes the REST API for guests. Improves security but may break some forms, frontend Gutenberg blocks, and integrations. Enable only after testing.'=>'Закрывает REST API для гостей. Повышает безопасность, но может сломатьнекоторые формы, блоки Gutenberg на фронте и интеграции. Включайте послепроверки.','Adds noindex for search results, attachment pages, and date archives. These pages are rarely useful in Google and often create duplicates. Different from General Settings → Disable site indexing, which blocks the entire site.'=>'Добавляет noindex для страниц поиска, вложений и архивов по датам. Этистраницы редко полезны в поиске Google и часто создают дубли. Отличается отGeneral Settings → Disable site indexing, который закрывает весь сайт.','Redirects author archive pages /author/name/ to the home page. Useful for a single-author blog. On a multi-author site it is better to leave this off.'=>'Перенаправляет страницы авторов /author/name/ на главную. Полезно для блогас одним автором. На мультиавторском сайте лучше выключить.','Prevents editing theme and plugin PHP files from the admin. Recommended for security: changes should go through git or FTP deliberately.'=>'Запрещает редактировать PHP-файлы тем и плагинов прямо из админки.Рекомендуется для безопасности: правки должны идти через git/FTP осознанно.','Disables Application Passwords for REST API access. Rarely needed; if you do not use external apps with WP access, it is safer to keep this enabled.'=>'Отключает Application Passwords — пароли приложений для REST API. Нужныредко; если не используете внешние приложения с доступом к WP, лучшезакрыть.','Removes global-styles and classic-theme-styles on the frontend. It may speed up classic themes but can break blocks and typography. Check the site appearance after enabling.'=>'Убирает global-styles и classic-theme-styles на фронте. Может ускорить сайтна классических темах, но иногда ломает блоки и типографику. Проверяйтевнешний вид после включения.','Removes REST API and oEmbed discovery links from the head. Visitors do not need them, and they reveal extra site structure.'=>'Убирает из <head> служебные ссылки на REST API и oEmbed. Посетителям они ненужны, зато лишняя информация о структуре сайта не светится.','Blocks requests to pixel.wp.com, stats.wp.com, and WordPress Events in the admin. Also disables WooCommerce/Jetpack tracking when those plugins are installed. Does not block core updates.'=>'Блокирует отправку статистики на pixel.wp.com, stats.wp.com и запросыWordPress Events в админке. Также отключает трекинг WooCommerce/Jetpack,если эти плагины установлены. Не мешает обновлениям ядра.','Как работают перенаправления'=>'Как работают перенаправления','Плагин отдаёт ответ %1$s и перенаправляет посетителя с одного адреса на другой. Указывайте пути без домена — от корня WordPress, например %2$s (не /wp/old-page/, если сайт в подпапке). Абсолютные URL (https://...) — только в поле «Куда». Запросы к %3$s и %4$s никогда не перенаправляются.'=>'Плагин отдаёт ответ %1$s и перенаправляет посетителя с одного адреса на другой. Указывайте пути без домена — от корня WordPress, например %2$s (не /wp/old-page/, если сайт в подпапке). Абсолютные URL (https://...) — только в поле «Куда». Запросы к %3$s и %4$s никогда не перенаправляются.','Слеш в конце URL'=>'Слеш в конце URL','/page и /page/ считаются одинаковыми. Можно писать в любом виде — плагин сравнивает пути без учёта завершающего слеша.'=>'/page и /page/ считаются одинаковыми. Можно писать в любом виде — плагин сравнивает пути без учёта завершающего слеша.','Простые правила'=>'Простые правила','Массовый импорт CSV'=>'Массовый импорт CSV','Одна строка = одно правило. Разделители: запятая, ; или табуляция. Строки с # — комментарии. После сохранения правила попадут в список ниже.'=>'Одна строка = одно правило. Разделители: запятая, ; или табуляция. Строки с # — комментарии. После сохранения правила попадут в список ниже.','Подстановочный знак * (не regex)'=>'Подстановочный знак * (не regex)','Это не полноценные регулярные выражения — поддерживается только символ *. Включите опцию «Подстановочные знаки» выше.'=>'Это не полноценные регулярные выражения — поддерживается только символ *. Включите опцию «Подстановочные знаки» выше.','Что важно помнить'=>'Что важно помнить','Параметры запроса (?utm=...) при сравнении не учитываются. Если правило совпало — редирект сработает и для URL с query string. Не создавайте циклы: /a → /b и /b → /a.'=>'Параметры запроса (?utm=...) при сравнении не учитываются. Если правило совпало — редирект сработает и для URL с query string. Не создавайте циклы: /a → /b и /b → /a.','Wordpress Addon'=>'Дополнения WP','General Settings'=>'Основные настройки','Tweaks'=>'Твики','Cache'=>'Кэш','Enable page caching'=>'Включить кэширование страниц','Main switch for enabling/disabling cache. When ON: all site pages are saved to cache. When OFF: cache is not used, pages are generated each time anew.'=>'Основной переключатель для включения/выключения кэширования. В положении «ВКЛ.»: все страницы сайта сохраняются в кэше. В положении «ВЫКЛ.»: кэш не используется, страницы генерируются каждый раз заново.','Cache lifetime (seconds)'=>'Время жизни кэша (секунды)','Do not cache for logged-in users'=>'Не кэшировать для зарегистрированных пользователей','If a user is logged into admin or personal account - show them fresh pages without cache. Otherwise, they may not see their changes or notifications.'=>'Если пользователь вошел в учетную запись администратора или личный кабинет, покажите ему свежие страницы без кэша. В противном случае он может не увидеть свои изменения или уведомления.','Do not cache these pages'=>'Не кэшируйте эти страницы','Pages that change frequently and should not be cached. One line - one URL. Examples: /wp-admin/ (admin), /checkout/ (checkout), /cart/ (cart), /my-account/ (personal account).'=>'Страницы, которые часто меняются и не должны кэшироваться. Одна строка — один URL. Примеры: /wp-admin/ (администрирование), /checkout/ (оформление заказа), /cart/ (корзина), /my-account/ (личный кабинет).','Preload these pages'=>'Предварительно загрузить эти страницы','Pages for auto-caching every hour. <strong>Leave empty for automatic mode:</strong> the home page + all pages from the main site menu (up to 10 pcs) will be loaded. Or specify manually: one URL per line, for example /about/, /services/'=>'Страницы для автоматического кэширования каждый час. <strong>Оставьте пустым для автоматического режима:</strong> будут загружены главная страница и все страницы главного меню сайта (до 10 шт.). Или укажите вручную: по одному URL на строку, например /about/, /services/','Clear cache on post publish'=>'Очистить кэш при публикации поста','When you publish a new article or edit an old one - automatically delete all cache. So readers will immediately see fresh content. Disable if you publish often - this will slow down the site.'=>'При публикации новой статьи или редактировании старой — автоматически удаляйте весь кэш. Так читатели сразу увидят свежий контент. Отключите, если публикуете часто — это замедлит работу сайта.','Asset Minification'=>'Минификация Assets','Asset optimization is a comprehensive system for improving site performance by minifying and combining CSS/JavaScript files. The module automatically analyzes all connected resources and applies optimal optimization strategies.<br><br><strong>Benefits:</strong><br>• Reduce file size by 20-40%<br>• Decrease number of HTTP requests<br>• Speed up page loading<br>• Better PageSpeed Insights scores<br><br><strong>Automatic logic:</strong><br>• Excludes WordPress system resources<br>• Does not process files smaller than 1KB<br>• Skips already minified files<br>• Analyzes resource loading priorities'=>'Оптимизация ресурсов — это комплексная система для повышения производительности сайта путём минификации и объединения CSS/JavaScript-файлов. Модуль автоматически анализирует все подключенные ресурсы и применяет оптимальные стратегии оптимизации.<br><br><strong>Преимущества:</strong><br>• Уменьшение размера файла на 20–40%<br>• Уменьшение количества HTTP-запросов<br>• Ускорение загрузки страниц<br>• Улучшение показателей PageSpeed Insights<br><br><strong>Автоматическая логика:</strong><br>• Исключение системных ресурсов WordPress<br>• Не обрабатывает файлы размером менее 1 КБ<br>• Пропускает уже минифицированные файлы<br>• Анализ приоритетов загрузки ресурсов','Enable asset optimization'=>'Включить оптимизацию активов','Main switch of the optimization module. When enabled, intelligent processing of all CSS and JavaScript resources on the site is activated. Recommended to enable on production sites for maximum performance.'=>'Главный переключатель модуля оптимизации. При включении активируется интеллектуальная обработка всех CSS и JavaScript-ресурсов на сайте. Рекомендуется включать на рабочих сайтах для максимальной производительности.','Minify CSS files'=>'Минифицировать CSS-файлы','Removes from CSS files: comments, extra spaces, line breaks and tabs. Does not process files that are already minified or smaller than 1KB. Traffic savings: 15-30% per file.'=>'Удаляет из CSS-файлов комментарии, лишние пробелы, переносы строк и табуляции. Не обрабатывает файлы, которые уже минифицированы или размером меньше 1 КБ. Экономия трафика: 15–30% на файл.','Minify JavaScript files'=>'Минифицировать файлы JavaScript','Compresses JS code by removing comments, extra spaces and formatting. Skips minified files and files smaller than 1KB. Important: check functionality after enabling, as some plugins may have minification-sensitive code.'=>'Сжимает JS-код, удаляя комментарии, лишние пробелы и форматирование. Пропускает минифицированные файлы и файлы размером менее 1 КБ. Важно: проверьте работоспособность после включения, так как некоторые плагины могут содержать код, чувствительный к минификации.','Combine CSS files'=>'Объединить CSS-файлы','Collects all suitable CSS files into one combined file, reducing the number of HTTP requests to the server. Automatically excludes WordPress system styles. Effective for sites with 3+ CSS files.'=>'Собирает все подходящие CSS-файлы в один общий файл, сокращая количество HTTP-запросов к серверу. Автоматически исключает системные стили WordPress. Эффективно для сайтов с тремя и более CSS-файлами.','Combine JavaScript files'=>'Объединить файлы JavaScript','Combines JS files into one loaded in the footer. Reduces the number of requests, but may break loading order. Recommended to test for JavaScript errors after enabling.'=>'Объединяет JS-файлы в один, загружаемый в нижний колонтитул. Уменьшает количество запросов, но может нарушить порядок загрузки. Рекомендуется проверить наличие ошибок JavaScript после включения.','Implement critical CSS'=>'Реализуйте критический CSS','Automatically extracts and embeds inline critical CSS styles (header, menu, main content) for instant display of above-the-fold content. Improves First Contentful Paint score in Lighthouse.'=>'Автоматически извлекает и встраивает критически важные встроенные стили CSS (заголовок, меню, основной контент) для мгновенного отображения контента в верхней части страницы. Улучшает показатель First Contentful Paint в Lighthouse.','Defer non-critical CSS'=>'Отложить некритический CSS','Loads non-critical CSS files asynchronously after page rendering. Prevents render blocking, but may cause brief "flash of unstyled content" (FOUC).'=>'Асинхронно загружает некритичные CSS-файлы после рендеринга страницы. Предотвращает блокировку рендеринга, но может вызывать кратковременное «вспышку нестилизованного контента» (FOUC).','Exclude CSS files'=>'Исключить файлы CSS','List of CSS file handles separated by comma that should not be optimized. Examples: critical-styles, admin-css, custom-admin-styles. WordPress system files are excluded automatically.'=>'Список дескрипторов CSS-файлов, разделённых запятыми, которые не следует оптимизировать. Примеры: critic-styles, admin-css, custom-admin-styles. Системные файлы WordPress автоматически исключаются.','Exclude JavaScript files'=>'Исключить файлы JavaScript','JS file handles separated by comma for exclusion from optimization. Examples: google-analytics, facebook-pixel, custom-scripts. WordPress system scripts (jQuery, etc.) are excluded automatically.'=>'Обработчики JS-файлов, разделенные запятой, исключают их из оптимизации. Примеры: google-analytics, facebook-pixel, custom-scripts. Системные скрипты WordPress (jQuery и т. д.) исключаются автоматически.','Lazy Loading'=>'Ленивая загрузка','Lazy loading of images and media files is a performance optimization technique where resources are loaded only when they come into the user\'s view. The module uses the modern Intersection Observer API with fallback for older browsers.<br><br><strong>Benefits:</strong><br>• Reduced page load time<br>• Traffic savings (especially on mobile devices)<br>• Improved Core Web Vitals (LCP, CLS)<br>• Automatic image compression with blur placeholder<br><br><strong>Support:</strong><br>• Images (img)<br>• Iframe (YouTube, Vimeo videos)<br>• Video elements<br>• Blur placeholder for smooth loading<br>• Fallback for IE11+'=>'Ленивая загрузка изображений и медиафайлов — это метод оптимизации производительности, при котором ресурсы загружаются только тогда, когда пользователь их видит. Модуль использует современный API Intersection Observer с возможностью отката для старых браузеров.<br><br><strong>Преимущества:</strong><br>• Сокращение времени загрузки страницы<br>• Экономия трафика (особенно на мобильных устройствах)<br>• Улучшение Core Web Vitals (LCP, CLS)<br>• Автоматическое сжатие изображений с использованием плейсхолдера размытия<br><br><strong>Поддержка:</strong><br>• Изображения (img)<br>• Iframe (видео YouTube, Vimeo)<br>• Видеоэлементы<br>• Размытие плейсхолдера для плавной загрузки<br>• Откат для IE11+','Enable lazy loading'=>'Включить ленивую загрузку','Main switch of the module. When enabled, lazy loading is activated for selected media types. Recommended to enable on all sites for improved performance.'=>'Главный переключатель модуля. При включении активируется отложенная загрузка для выбранных типов медиа. Рекомендуется включить на всех сайтах для повышения производительности.','Media types for lazy loading'=>'Типы носителей для ленивой загрузки','Select element types for which lazy loading will be applied. Images are most effective for optimization.'=>'Выберите типы элементов, к которым будет применяться ленивая загрузка. Изображения наиболее эффективны для оптимизации.','Images (img)'=>'Изображения (img)','Iframe (YouTube, Vimeo)'=>'Iframe (YouTube, Vimeo)','Video elements'=>'Видеоэлементы','Blur effect intensity'=>'Интенсивность эффекта размытия','Degree of blur placeholder blur. Value 1 - weak blur, 10 - strong. Recommended 3-7 for optimal quality and performance balance.'=>'Степень размытия. Значение 1 — слабое размытие, 10 — сильное. Рекомендуется 3–7 для оптимального баланса качества и производительности.','Viewport margin (rootMargin)'=>'Поле области просмотра (rootMargin)','Distance from viewport edge at which to start loading. Example: 50px - loading 50px before element appears. 10% - 10% of viewport height.'=>'Расстояние от края области просмотра, с которого начинается загрузка. Пример: 50 пикселей — загрузка за 50 пикселей до появления элемента. 10% — 10% от высоты области просмотра.','Visibility threshold'=>'Порог видимости','The portion of the element that must enter the viewport to start loading. 0.1 = 10% of element visible. 1.0 = entire element visible.'=>'Часть элемента, которая должна попасть в область просмотра, чтобы началась загрузка. 0,1 = 10% видимого элемента. 1,0 = виден весь элемент.','Enable fallback for older browsers'=>'Включить откат для старых браузеров','Use scroll event listeners instead of Intersection Observer in browsers without IO API support. Slows performance but ensures compatibility.'=>'Используйте прослушиватели событий прокрутки вместо Intersection Observer в браузерах без поддержки API ввода-вывода. Снижает производительность, но обеспечивает совместимость.','Media Cleanup'=>'Очистка медиа','This section allows you to clean up unused image sizes to free up disk space. WordPress generates multiple sizes for each uploaded image, but if your theme or plugins don\'t use all of them, they take up unnecessary space. Use this tool to identify and remove such files.<br><br><strong>When to use:</strong> After changing themes, disabling plugins that generate custom sizes, or optimizing site performance.<br><br><strong>Precautions:</strong> Always create a backup before cleanup. Use "Preview Cleanup" first to see what will be deleted. The tool preserves original images and "scaled" versions (up to 2000px). Deleted files cannot be recovered!'=>'Этот раздел позволяет очистить неиспользуемые размеры изображений, чтобы освободить место на диске. WordPress генерирует несколько размеров для каждого загруженного изображения, но если ваша тема или плагины не используют их все, они занимают лишнее место. Используйте этот инструмент для выявления и удаления таких файлов.<br><br><strong>Когда использовать:</strong> После смены темы, отключения плагинов, генерирующих нестандартные размеры, или оптимизации производительности сайта.<br><br><strong>Меры предосторожности:</strong> Всегда создавайте резервную копию перед очисткой. Сначала воспользуйтесь функцией «Предварительная очистка», чтобы увидеть, что будет удалено. Инструмент сохраняет исходные изображения и «масштабированные» версии (до 2000 пикселей). Удаленные файлы не подлежат восстановлению!','Enable Media Cleanup'=>'Очистка медиа','Clean up unused image sizes'=>'Очистите неиспользуемые размеры изображений','This will delete all image sizes except: %s. Files will be deleted permanently!'=>'Это приведет к удалению всех размеров изображений, кроме: %s. Файлы будут удалены безвозвратно!','Preview Cleanup'=>'Очистка предварительного просмотра','Start Cleanup'=>'Начать очистку','Loading preview...'=>'Загрузка предварительного просмотра...','Are you sure? This action cannot be undone.'=>'Вы уверены? Это действие нельзя отменить.','Processing...'=>'Обработка...','Redirects'=>'Перенаправления','301 redirect management for old URLs, moved pages and bulk migrations. Read the guide below for slash rules, wildcard examples and CSV import format.'=>'Управление перенаправлениями 301 для старых URL, перенесённых страниц и массовых миграций. Ниже — подробная инструкция: слеши, примеры с * и формат CSV.','Enable redirects'=>'Включить надстройку 301 редиректа?','When disabled, redirect rules are saved but not applied on the site.'=>'Если выключено — правила сохраняются, но на сайте не применяются.','Use wildcard redirects'=>'Используйте подстановочные знаки перенаправления','Required for rules with *. Without this option only exact URL matches work, e.g. /old-page/ → /new-page/.'=>'Обязательно для правил с *. Без этой опции работают только точные совпадения, например /old-page/ → /new-page/.','Bulk CSV import'=>'Массовый импорт из CSV','Paste rules here and save settings. Format: source,destination — one rule per line. Duplicate source URLs are overwritten. The field is cleared after a successful import.'=>'Вставьте правила и сохраните настройки. Формат: исходный-url,целевой-url — одно правило на строку. Дубликаты по исходному URL перезаписываются. После успешного импорта поле очищается.','Redirect rules'=>'Правила перенаправления','Manual rule list. «Request URL» is the old address visitors open. «Destination URL» is where they should land. Trailing slashes are optional.'=>'Список правил вручную. «Исходный URL» — старый адрес, который открывает посетитель. «Целевой URL» — куда его перенаправить. Завершающий слеш не обязателен.','Request URL'=>'URL-адрес запроса','Old URL path relative to site root. Examples: /old-page/, /old-page (same), /old-folder/* with wildcards enabled.'=>'Путь старого URL относительно корня сайта. Примеры: /old-page/, /old-page (то же самое), /old-folder/* при включённых подстановочных знаках.','Destination URL'=>'URL-адрес назначения','New address: site path (/new-page/) or full URL (https://example.com/page/). For wildcards use * in the same position as in the source.'=>'Новый адрес: путь на сайте (/new-page/) или полный URL (https://example.com/page/). Для * указывайте звёздочку в той же позиции, что и в исходном URL.','Shortcodes and Widgets'=>'Шорткоды и виджеты','Custom code'=>'Свой код','CSS Code in Header'=>'CSS-код в Header','Any HTML code or Analytics code in header.'=>'Любой HTML-код или код Analytics в header.','Any HTML code in footer.'=>'Любой HTML-код в футере.','Post types'=>'Выбор post type','Live preview'=>'Загрузка предварительного просмотра...','Backup Settings'=>'Бэкап','Download settings now'=>'Скачать настройки','Disable guttenberg for widgets'=>'Отключить Гуттенберг для виджетов','Enable Duplicate widgets'=>'Включить дублирование виджетов','Components'=>'Компоненты','Enable FAQ shortcode'=>'Включить шорткод FAQ','WPBakery Page Builder support '=>'Поддержка конструктора страниц WPBakery','Enable Table of Content shortcode'=>'Включить шорткод таблицы содержания','Yearly archive widget'=>'Виджет ежегодного архива','by Aleksey Tihomirov'=>'от Алексей Тихомиров','With love by <span style="color: #ED4301;">A</span> Tikhomirov'=>'С любовью <span style="color: #ED4301;">A</span> Tikhomirov','Removes /category/ from category URLs. Permalinks are flushed automatically when this option changes.'=>'Убирает /category/ из URL категорий. Постоянные ссылки сбрасываются автоматически при изменении этой опции.','Enables pretty URLs for nested tags such as /tag/git/submodules/. The rewrite rule maps to the final tag slug, not the full path. Permalinks are flushed automatically when this option changes.'=>'Включает красивые URL для вложенных тегов, например /tag/git/submodules/. Правило rewrite ведёт на конечный slug тега, а не на весь путь. Постоянные ссылки сбрасываются автоматически при изменении этой опции.','Categories to hide on the frontend'=>'Категории, скрываемые на фронтенде','Select categories that should be hidden from archives, feeds, and direct category URLs. Legacy comma-separated IDs are still supported.'=>'Выберите категории, которые нужно скрыть из архивов, RSS и прямых URL категорий. Старый формат ID через запятую по-прежнему поддерживается.','Bootstrap 3 is the supported framework for the current theme and shortcodes. Bootstrap 5 and Tailwind are reserved for future use and may not match the frontend styles yet.'=>'Bootstrap 3 — поддерживаемый фреймворк для текущей темы и шорткодов. Bootstrap 5 и Tailwind зарезервированы на будущее и могут не совпадать со стилями фронтенда.','Bootstrap 3 (recommended)'=>'Bootstrap 3 (рекомендуется)','Bootstrap 5 (future)'=>'Bootstrap 5 (в будущем)','Tailwind CSS (future)'=>'Tailwind CSS (в будущем)','Filter by role'=>'Фильтр по роли','You do not have permission to access this page.'=>'У вас нет прав для доступа к этой странице.','Update all GUID fields in the posts table with permalinks.'=>'Обновить все поля GUID в таблице posts постоянными ссылками.','View all revisions stored in the posts table.'=>'Просмотреть все ревизии в таблице posts.','Delete all revisions and related rows.'=>'Удалить все ревизии и связанные записи.','Bulk GUID replacement'=>'Массовая замена GUID','This action replaces GUID values for all published public posts with their permalinks. RSS subscribers may receive duplicate items.'=>'Это действие заменит GUID у всех опубликованных публичных записей на их постоянные ссылки. Подписчики RSS могут получить дубликаты материалов.','Replace GUID values for all published posts?'=>'Заменить GUID у всех опубликованных записей?','Replace all GUID values'=>'Заменить все GUID','The query returned no results.'=>'Запрос не вернул результатов.','Updated:'=>'Обновлено:','Previous GUID: %s'=>'Предыдущий GUID: %s','Not updated:'=>'Не обновлено:','Post or page ID'=>'ID записи или страницы','All revisions were removed from posts and related rows in term_relationships, postmeta, and comments.'=>'Все ревизии удалены из posts и связанных строк в term_relationships, postmeta и comments.','No revisions found.'=>'Ревизии не найдены.']];